arrivals = [0, 0, 1, 2, 2]
steps = 6
active = []
finished = set()
log = []
for t in range(steps):
    for rid, a in enumerate(arrivals):
        if a == t:
            active.append(rid)
    batch = [r for r in active if r not in finished]
    if batch:
        log.append((t, list(batch)))
    if batch:
        finished.add(batch[0])
print("迭代调度日志 (步, 批内请求):")
for step, b in log:
    print(f"  step {step}: {b}")
print("已完成请求数:", len(finished))
